      "source_id": "h4",
      "actor": "system",
      "role": "tool response",
      "fact": "get_customer_by_phone returns two customers: C2044 (phone 555-201-3344, lines L2101/L2102) and C2090 (same name, no phone shown, line L2950)"
    },
    {
      "source_id": "h5",
